let C,editC,courseETag,overview,view=learner?'study':'overview',unitId,taskId,editUnitId,courseDirty=false,selection=0;
let schedule,scheduleETag,preview=null,previewReviewOnly=false,gitOffset=0,gitItems=[],gitRequest=0,compareAction=null,dialogSave=null;
const docs=new Map(),drafts=new Map(),dirtyUnits=new Set(),pendingRecords=new Map(),reviewDocs=new Map(),unitEdits=new Map(),draftDirty=new Set(),assessmentDirty=new Set();
let slots=[],candidateItems=[],sourceReviews=[],sourceBaseline=[];
const questionSnapshots=new Map(),scheduleBackups=[];
let scheduleTouched=false,sourceContext=null,scheduleInitialized=false;
const activeUnits=course=>(course?.units||[]).filter(u=>!u.archived&&!(course.stages||[]).find(s=>s.id===u.stageId)?.archived);
const currentUnit=()=>C.units.find(u=>u.id===unitId);
