function captureSourceReview(){document.querySelectorAll('[data-review-item]').forEach(el=>{const item=sourceReviews.find(i=>i.itemId===el.dataset.reviewItem);el.querySelectorAll('[data-review-field]').forEach(input=>item[input.dataset.reviewField]=input.dataset.reviewField==='remainingMinutes'?Number(input.value):input.value);const evidence=el.querySelector('[data-evidence-loaded]');if(evidence)item.recordIds=[...evidence.querySelectorAll('[data-review-record]:checked')].map(input=>input.dataset.reviewRecord);});}
async function loadSourceEvidence(revisionId){const unitIds=[...new Set(sourceReviews.map(i=>taskMap().get(i.taskId)?.u.id).filter(Boolean))];const results=await Promise.allSettled(unitIds.map(async id=>reviewDocs.set(id,await request(`/api/admin/units/${encodeURIComponent(id)}`))));for(const r of results)if(r.status==='rejected')throw r.reason;if(latestWeek(monday($('source-week').value))?.revisions.at(-1)?.id!==revisionId)return;for(const i of sourceReviews){const entry=taskMap().get(i.taskId),records=entry?effectiveRecords(reviewDocs.get(entry.u.id).data).filter(r=>r.taskId===i.taskId):[];const box=document.querySelector(`[data-review-evidence="${CSS.escape(i.itemId)}"]`);if(!box)continue;const missing=(i.recordIds||[]).some(id=>!records.some(r=>r.id===id));box.innerHTML=`<div data-evidence-loaded><p class="muted">关联真实训练记录（标为已做完时需要证据，请核对后勾选）</p>${records.map(r=>`<label class="check"><input type="checkbox" data-review-record="${esc(r.id)}"${i.recordIds.includes(r.id)?' checked':''}><span>${esc(r.date)} · ${r.minutes} 分钟 · ${OUTCOME[r.outcome]}${r.scheduleItemId===i.itemId?' · 对应本片段':''}<br><small>${esc(r.result.slice(0,100))}</small></span></label>`).join('')||`<p class="muted">${learner?'还没有这个任务的有效训练记录；可先去“训练与记录”补记真实日期和证据。':'还没有这个任务的有效训练记录，请学习者补记真实训练；管理者不代填证据。'}</p>`}${missing?'<p class="notice">原核对关联的记录已被更正，请重新选择当前有效版本。</p>':''}</div>`;}}
