function capacityPreset(count){const start=monday($('target-week').value||today());slots=(count===4?[0,2,4,6]:count===2?[1,5]:[]).map(n=>({id:uid('slot'),date:addDays(start,n),start:'19:00',minutes:180,bufferMinutes:30})).filter(s=>s.date>=today());if(count===0){$('resume-minutes').value=0;}renderSlots();invalidatePreview();}
