async function previewSchedule(reviewOnly=false){captureSlots();captureCandidateItems();captureSourceReview();const start=monday($('target-week').value);if(!start)throw Error('请选择有效的目标周');const review=getReview();if(reviewOnly&&!review)throw Error('来源周还没有安排，无需保存核对');const chosen=reviewOnly?[]:candidateItems.filter(i=>i.selected).map(({id,taskId,goal,estimatedMinutes,continuedFromItemId,kind})=>({id,taskId,goal,estimatedMinutes,continuedFromItemId,kind:kind||'work'}));const refreshMinutes=Number($('resume-minutes').value||0);if(!reviewOnly&&refreshMinutes>0&&chosen.length){const first=chosen[0];chosen.unshift({id:uid('item'),taskId:first.taskId,goal:'恢复自测：独立解释或复现最近成果，检查后再续做。',kind:'recovery-check',estimatedMinutes:refreshMinutes,continuedFromItemId:''});}const body={requestId:uid('schedule'),weekStart:start,reason:$('schedule-reason').value.trim()||(slots.length?'按实际容量安排学习':'本周暂停'),slots:reviewOnly?[]:slots,items:chosen,review,resumeDate:$('resume-date').value||''};preview=(await request('/api/admin/schedule/preview',{method:'POST',body:JSON.stringify(body)})).data;previewReviewOnly=reviewOnly;renderPreview();}
function renderPreview(){const p=preview,plan=p.plan;$('schedule-preview').innerHTML=`<p class="eyebrow">${esc(plan.weekStart)} 起的一周${previewReviewOnly?' · 仅核对':''}</p><p><strong>${p.capacityMinutes}</strong> 分钟可用 · <strong>${p.plannedMinutes}</strong> 分钟已安排 · <strong>${p.bufferMinutes}</strong> 分钟缓冲</p>${previewReviewOnly?'<div class="notice">本次只追加来源周核对，不发布目标周安排。</div>':''}${(p.warnings||[]).map(v=>`<p class="notice">${esc(typeof v==='string'?v:JSON.stringify(v))}</p>`).join('')}${(p.reminders||[]).map(v=>`<p class="muted">${esc(typeof v==='string'?v:JSON.stringify(v))}</p>`).join('')}${plan.slots.map(s=>`<div class="schedule-review"><h4>${esc(s.date)} ${esc(s.start)} · ${s.minutes} 分钟</h4>${s.items.map(i=>`<p>${esc(i.goal)} <span class="muted">${i.estimatedMinutes} 分钟</span></p>`).join('')||'<p class="muted">本时段留空，按实际掌握情况再安排。</p>'}<p class="muted">缓冲 ${s.bufferMinutes} 分钟</p></div>`).join('')||'<p class="empty">本周暂停，已有证据和用时保持原样。</p>'}${plan.unassigned.length?`<h4 class="field">本次待安排</h4>${plan.unassigned.map(i=>`<p class="muted">${esc(i.goal)} · ${i.estimatedMinutes} 分钟</p>`).join('')}`:''}`;$('preview-actions').hidden=false;}
