function renderScheduleSaved(){const weeks=(schedule?.weeks||[]).slice().sort((a,b)=>b.weekStart.localeCompare(a.weekStart));$('saved-weeks').innerHTML=weeks.map(w=>{const r=w.revisions.at(-1);return `<div class="editor-row"><div class="grow"><strong>${esc(w.weekStart)} 起的一周</strong><p class="muted">${r?.slots.length?`${r.slots.length} 个时段 · ${r.slots.reduce((n,s)=>n+s.minutes,0)} 分钟`:'暂停 / 仅有核对'} · ${w.revisions.length} 版安排 · ${w.reviews.length} 次核对</p></div><button data-load-week="${esc(w.weekStart)}">查看与调整</button></div>`;}).join('')||'<p class="empty">还没有自然周安排。</p>';$('schedule-history').innerHTML=weeks.flatMap(w=>[...w.revisions.map((r,i)=>({kind:'revision',week:w.weekStart,n:i+1,...r})),...w.reviews.map(r=>({kind:'review',week:w.weekStart,...r}))]).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,40).map(r=>`<details><summary>${esc(r.week)} · ${r.kind==='revision'?`第 ${r.n} 版安排`:'执行核对'} · ${esc(r.createdAt?.slice(0,10)||'')}</summary><p class="muted">${esc(r.reason||r.note||'按实际情况调整')}</p>${r.kind==='revision'?`${r.slots.map(s=>`<p class="muted">${esc(s.date+' '+s.start)} · ${s.minutes} 分钟 · 缓冲 ${s.bufferMinutes}</p>${s.items.map(i=>`<p class="muted">${esc(i.goal)} (${i.estimatedMinutes} 分钟)</p>`).join('')}`).join('')||'<p class="muted">暂停周</p>'}${r.unassigned?.length?`<p class="muted">待安排：${r.unassigned.map(i=>esc(i.goal)).join('；')}</p>`:''}`:r.items.map(i=>`<p class="muted">${esc(i.itemId)} · ${{done:'片段已做完',partial:'部分完成','not-started':'尚未开始',unknown:'待核对'}[i.outcome]} · ${esc(i.next)}</p>`).join('')}</details>`).join('')||'<p class="muted">应用安排后会保留每次修订，原定安排不会被覆盖。</p>';}
async function loadGit(reset=false){const seq=++gitRequest;if(reset){gitOffset=0;gitItems=[];}const data=(await request(`/api/admin/history?kind=${encodeURIComponent(gitKind)}&offset=${gitOffset}&limit=20`)).data;if(seq!==gitRequest)return;gitItems.push(...data.items);gitOffset=data.nextOffset??gitItems.length;$('git-status').textContent=[data.message,data.learnerEmail?'学习者 Author 邮箱：'+data.learnerEmail:'学习者邮箱尚未有效配置',data.branch?'分支：'+data.branch:'',data.scope,data.shallow?'浅克隆，历史可能不完整':''].filter(Boolean).join(' · ');$('git-history').innerHTML=gitItems.map(r=>`<article class="record"><div class="record-head"><span>${r.kind==='learning'?'学习记录':r.kind==='maintenance'?'维护记录':'未分类'}${r.merge?' · 合并提交':''}</span><code>${esc(r.shortHash)}</code></div><h4>${esc(r.subject)}</h4><p class="muted">${esc(r.authorName)} &lt;${esc(r.authorEmail)}&gt;</p><p class="muted">${esc(r.authorDate)}${r.committerEmail!==r.authorEmail?' · Committer '+esc(r.committerEmail):''}</p></article>`).join('')||'<p class="empty">当前范围没有可展示的提交。</p>';$('git-more').hidden=!data.hasMore;}
